window.POETRY_REGISTER("v5-extra-5-13-0-b591f25b4b8c.js",{"poems":[[10743,2],[51922,2],[52300,2],[52802,2],[54185,2],[54573,2],[54628,2],[55327,2],[55678,2],[57968,2],[96506,7],[233355,7],[233442,7],[260441,7],[272019,7],[290723,7],[306887,7],[313684,7],[340166,9],[340208,9],[345477,9],[351001,9],[358940,9],[473778,8],[573945,8],[650305,5],[657023,5],[659213,5],[673647,5],[723307,5],[726206,5],[727360,5],[744367,21]],"pairs":[["遗我双玉璞","云是古之得道者西王母食之余",0],["严助终军也","二人乃汉武帝时文士有武略者",1],["我来谁与朋","按诗前署者暨县令郭密之七字",2],["即至葱岭镇","开元十五年十一月上旬至安西",3],["亦难以遽断","处约孙长卿以天宝后期第进士",4],["其时已较后","颇此人即与钱起有过往之杨绾",5],["详此段纪事","似巨川于朱泚乱时亦陷身贼中",6],["余在南中日","知家累以其年九月九日发衡州",7],["亦号归元子","唐僖宗时隐炼于金鸡关下石室",8],["又明年李贬","盖当时疾李者托名为之附于集",9],["退不隐山林","与之游者但爱其人而莫见其术",10],["无人触虚舟","何曾见尔悬旌鸣佩朗装欲飞动",11],["耳热徒歌讴","可以销遣绵绵不断万古之悲愁",11],["丹穴兮优游","何蜂虫之阴戾琐微兮藏形于暗",12],["钩上珊瑚枝","丰城地下掘起龙泉太阿双宝剑",13],["而惟是之归","予知其必有以助善政于熙丰也",14],["肺渴方生尘","不知谁何驷六虬兮上天作乐府",15],["天高叫无路","开先拄杖子忽然变作空行龙王",16],["类焉个枯桥","似者般无禅无道无能为底长老",17],["盥手屡叩头","润泽善利责望水兴云作雨嘑噏",18],["馈遗及友生","何必黄尘赤日飘缨纡组趋神京",19],["南望而思乡","溯孤鸿之影灭兮书不得而远寄",20],["听终各自愁","为问竹枝芦叶若为写出秦青讴",21],["足蹑香炉烟","但见飞霞笑电摇光九道叠云锦",22],["左顾招广成","神农以还九千九百九十有馀帝",23],["沿月兮棹讴","彼坳堂之杯兮孰若以芥而为舟",24],["尔不高腾空","安得受制于人垂头仰饲居樊笼",25],["诗编巨岳集","书有姜体远本周之史籀秦相斯",26],["明月对我影","外此惟有酒徒诗客可与相周旋",27],["尔亦腼然人","甘与分尸之桧万年遗臭独何心",28],["欲语复呜咽","但得兄嫂一心善事阿母常喜悦",29],["顷刻千言就","握管如君多逸思犹伴阶除鹤瘦",30],["玉笛吹都遍","弹指十年重叠恨偏到今朝凄断",31],["星稀兮月明","亭檐隅以逍遥兮盻太虚以仰观",32]]});
